$('toggle-overseas').onclick=()=>{const open=$('overseas-menu').hidden;$('overseas-menu').hidden=!open;$('toggle-overseas').setAttribute('aria-expanded',String(open));if(open)setMapPanel(null);};
function placeCity(lat,lng,zoom=10){moved();center=[lng,lat];draw();map.setView([lat,lng],zoom,{animate:false});placed();}
// Menu icons come from the small precomputed index; the full overseas data loads when needed.
for(const p of window.OVERSEAS_INDEX.territories){const button=document.createElement('button');button.className='territory-icon';button.setAttribute('aria-label',p.nom);button.title=p.nom;
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),path=document.createElementNS(ns,'path');svg.setAttribute('viewBox','0 0 64 64');svg.setAttribute('aria-hidden','true');path.setAttribute('d',p.path);svg.append(path);const name=document.createElement('span');name.className='territory-tooltip';name.textContent=p.nom;button.append(svg,name);button.onclick=()=>{$('overseas-menu').hidden=true;$('toggle-overseas').setAttribute('aria-expanded','false');placeCity(p.lat,p.lng,p.zoom);};$('overseas-options').append(button);}
$('overseas-menu').addEventListener('keydown',e=>{if(e.key==='Escape'){$('overseas-menu').hidden=true;$('toggle-overseas').setAttribute('aria-expanded','false');$('toggle-overseas').focus();}});
let searchTimer,searchAbort,searchSequence=0;
const normalize=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
$('search-city').addEventListener('input',()=>{clearTimeout(searchTimer);searchAbort?.abort();const request=++searchSequence,q=$('search-city').value.trim();$('city-results').replaceChildren();$('city-results').hidden=true;$('search-feedback').textContent='';if(q.length<2)return;searchTimer=setTimeout(async()=>{searchAbort=new AbortController();$('search-feedback').textContent='Recherche…';let french=[],failed=false;try{const params=new URLSearchParams({...(/^\d{5}$/.test(q)?{codePostal:q}:{nom:q}),fields:'nom,code,population,centre,codesPostaux,departement',boost:'population',limit:8});const response=await fetch('https://geo.api.gouv.fr/communes?'+params,{signal:searchAbort.signal});if(!response.ok)throw Error();french=await response.json();}catch(e){if(e.name==='AbortError')return;failed=true;}if(request!==searchSequence)return;const local=[...swiss.communes.features,...window.OVERSEAS_INDEX.places.map(p=>({properties:p}))].filter(f=>normalize(f.properties.nom).includes(normalize(q))).sort((a,b)=>(b.properties.population||0)-(a.properties.population||0)).slice(0,8).map(f=>({...f.properties,centre:f.properties.centre||turf.pointOnFeature(f).geometry}));const arr=arrondissementPlaces.filter(p=>normalize(p.nom).includes(normalize(q))||p.codesPostaux.includes(q)).map(p=>({...p,nom:p.nom.replace(' Arrondissement',''),arrondissement:true}));const choices=[...new Map([...local,...french,...arr].filter(p=>p.centre?.coordinates).map(p=>[p.code,p])).values()].sort((a,b)=>{const exact=p=>normalize(p.nom)===normalize(q);return Number(exact(b))-Number(exact(a))||Number(Boolean(b.arrondissement))-Number(Boolean(a.arrondissement))||(a.arrondissement&&b.arrondissement?a.nom.localeCompare(b.nom,'fr',{numeric:true}):(b.population||0)-(a.population||0));}).slice(0,30);$('search-feedback').textContent=failed?'La recherche des communes françaises ne répond pas. Résultats limités à la Suisse, à l’outre-mer et aux arrondissements.':choices.length?'':'Aucune commune trouvée.';for(const p of choices){const button=document.createElement('button');const label=document.createElement('strong'),detail=document.createElement('small');label.textContent=p.nom;detail.textContent=p.country==='CH'?'Suisse':p.nom==='Paris'?'Tous les arrondissements · Paris':p.codesPostaux?.length?p.codesPostaux.join(' · ')+(p.departement?.nom?' · '+p.departement.nom:''):'France · outre-mer';button.append(label,detail);button.onclick=()=>{++searchSequence;searchAbort?.abort();$('search-city').value=p.nom;$('city-results').hidden=true;$('search-feedback').textContent='';placeCity(p.centre.coordinates[1],p.centre.coordinates[0]);};$('city-results').append(button);}$('city-results').hidden=!choices.length;},300);});
$('search-city').addEventListener('keydown',e=>{if(e.key==='Escape'){$('city-results').hidden=true;++searchSequence;searchAbort?.abort();}if(e.key==='ArrowDown'){e.preventDefault();$('city-results').querySelector('button')?.focus();}if(e.key==='Enter'){e.preventDefault();$('city-results').querySelector('button')?.click();}});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#city-search'))$('city-results').hidden=true;});
window.refreshMapExtras();

